macro_rules! deps {
    () => {
        Iter!();
        Bits!();
        IterNames!();
        IterDefinedNames!();
        Flag!();
    };
}

macro_rules! Flags {
    () => {
        deps!();
        # [doc = "\nA set of defined flags using a bits type as storage.\n\n## Implementing `Flags`\n\nThis trait is implemented by the [`bitflags`](macro.bitflags.html) macro:\n\n```\nuse bitflags::bitflags;\n\nbitflags! {\n    struct MyFlags: u8 {\n        const A = 1;\n        const B = 1 << 1;\n    }\n}\n```\n\nIt can also be implemented manually:\n\n```\nuse bitflags::{Flag, Flags};\n\nstruct MyFlags(u8);\n\nimpl Flags for MyFlags {\n    const FLAGS: &'static [Flag<Self>] = &[\n        Flag::new(\"A\", MyFlags(1)),\n        Flag::new(\"B\", MyFlags(1 << 1)),\n    ];\n\n    type Bits = u8;\n\n    fn from_bits_retain(bits: Self::Bits) -> Self {\n        MyFlags(bits)\n    }\n\n    fn bits(&self) -> Self::Bits {\n        self.0\n    }\n}\n```\n\n## Using `Flags`\n\nThe `Flags` trait can be used generically to work with any flags types. In this example,\nwe can count the number of defined named flags:\n\n```\n# use bitflags::{bitflags, Flags};\nfn defined_flags<F: Flags>() -> usize {\n    F::FLAGS.iter().filter(|f| f.is_named()).count()\n}\n\nbitflags! {\n    struct MyFlags: u8 {\n        const A = 1;\n        const B = 1 << 1;\n        const C = 1 << 2;\n\n        const _ = !0;\n    }\n}\n\nassert_eq!(3, defined_flags::<MyFlags>());\n```\n"] pub trait Flags : Sized + 'static { # [doc = " The set of defined flags."] const FLAGS : & 'static [Flag < Self >] ; # [doc = " The underlying bits type."] type Bits : Bits ; # [doc = " Get a flags value with all bits unset."] fn empty () -> Self { Self :: from_bits_retain (Self :: Bits :: EMPTY) } # [doc = " Get a flags value with all known bits set."] fn all () -> Self { let mut truncated = Self :: Bits :: EMPTY ; for flag in Self :: FLAGS . iter () { truncated = truncated | flag . value () . bits () ; } Self :: from_bits_retain (truncated) } # [doc = " This method will return `true` if any unknown bits are set."] fn contains_unknown_bits (& self) -> bool { Self :: all () . bits () & self . bits () != self . bits () } # [doc = " Get the underlying bits value."] # [doc = ""] # [doc = " The returned value is exactly the bits set in this flags value."] fn bits (& self) -> Self :: Bits ; # [doc = " Convert from a bits value."] # [doc = ""] # [doc = " This method will return `None` if any unknown bits are set."] fn from_bits (bits : Self :: Bits) -> Option < Self > { let truncated = Self :: from_bits_truncate (bits) ; if truncated . bits () == bits { Some (truncated) } else { None } } # [doc = " Convert from a bits value, unsetting any unknown bits."] fn from_bits_truncate (bits : Self :: Bits) -> Self { Self :: from_bits_retain (bits & Self :: all () . bits ()) } # [doc = " Convert from a bits value exactly."] fn from_bits_retain (bits : Self :: Bits) -> Self ; # [doc = " Get a flags value with the bits of a flag with the given name set."] # [doc = ""] # [doc = " This method will return `None` if `name` is empty or doesn't"] # [doc = " correspond to any named flag."] fn from_name (name : & str) -> Option < Self > { if name . is_empty () { return None ; } for flag in Self :: FLAGS { if flag . name () == name { return Some (Self :: from_bits_retain (flag . value () . bits ())) ; } } None } # [doc = " Yield a set of contained flags values."] # [doc = ""] # [doc = " Each yielded flags value will correspond to a defined named flag. Any unknown bits"] # [doc = " will be yielded together as a final flags value."] fn iter (& self) -> iter :: Iter < Self > { iter :: Iter :: new (self) } # [doc = " Yield a set of contained named flags values."] # [doc = ""] # [doc = " This method is like [`Flags::iter`], except only yields bits in contained named flags."] # [doc = " Any unknown bits, or bits not corresponding to a contained flag will not be yielded."] fn iter_names (& self) -> iter :: IterNames < Self > { iter :: IterNames :: new (self) } # [doc = " Yield a set of all named flags defined by [`Self::FLAGS`]."] fn iter_defined_names () -> iter :: IterDefinedNames < Self > { iter :: IterDefinedNames :: new () } # [doc = " Whether all bits in this flags value are unset."] fn is_empty (& self) -> bool { self . bits () == Self :: Bits :: EMPTY } # [doc = " Whether all known bits in this flags value are set."] fn is_all (& self) -> bool { Self :: all () . bits () | self . bits () == self . bits () } # [doc = " Whether any set bits in a source flags value are also set in a target flags value."] fn intersects (& self , other : Self) -> bool where Self : Sized , { self . bits () & other . bits () != Self :: Bits :: EMPTY } # [doc = " Whether all set bits in a source flags value are also set in a target flags value."] fn contains (& self , other : Self) -> bool where Self : Sized , { self . bits () & other . bits () == other . bits () } # [doc = " Remove any unknown bits from the flags."] fn truncate (& mut self) where Self : Sized , { * self = Self :: from_bits_truncate (self . bits ()) ; } # [doc = " The bitwise or (`|`) of the bits in two flags values."] fn insert (& mut self , other : Self) where Self : Sized , { * self = Self :: from_bits_retain (self . bits ()) . union (other) ; } # [doc = " The intersection of a source flags value with the complement of a target flags value (`&!`)."] # [doc = ""] # [doc = " This method is not equivalent to `self & !other` when `other` has unknown bits set."] # [doc = " `remove` won't truncate `other`, but the `!` operator will."] fn remove (& mut self , other : Self) where Self : Sized , { * self = Self :: from_bits_retain (self . bits ()) . difference (other) ; } # [doc = " The bitwise exclusive-or (`^`) of the bits in two flags values."] fn toggle (& mut self , other : Self) where Self : Sized , { * self = Self :: from_bits_retain (self . bits ()) . symmetric_difference (other) ; } # [doc = " Call [`Flags::insert`] when `value` is `true` or [`Flags::remove`] when `value` is `false`."] fn set (& mut self , other : Self , value : bool) where Self : Sized , { if value { self . insert (other) ; } else { self . remove (other) ; } } # [doc = " Unsets all bits in the flags."] fn clear (& mut self) where Self : Sized , { * self = Self :: empty () ; } # [doc = " The bitwise and (`&`) of the bits in two flags values."] # [must_use] fn intersection (self , other : Self) -> Self { Self :: from_bits_retain (self . bits () & other . bits ()) } # [doc = " The bitwise or (`|`) of the bits in two flags values."] # [must_use] fn union (self , other : Self) -> Self { Self :: from_bits_retain (self . bits () | other . bits ()) } # [doc = " The intersection of a source flags value with the complement of a target flags value (`&!`)."] # [doc = ""] # [doc = " This method is not equivalent to `self & !other` when `other` has unknown bits set."] # [doc = " `difference` won't truncate `other`, but the `!` operator will."] # [must_use] fn difference (self , other : Self) -> Self { Self :: from_bits_retain (self . bits () & ! other . bits ()) } # [doc = " The bitwise exclusive-or (`^`) of the bits in two flags values."] # [must_use] fn symmetric_difference (self , other : Self) -> Self { Self :: from_bits_retain (self . bits () ^ other . bits ()) } # [doc = " The bitwise negation (`!`) of the bits in a flags value, truncating the result."] # [must_use] fn complement (self) -> Self { Self :: from_bits_truncate (! self . bits ()) } }
    };
}

Flags!()